pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address target, uint256 value, bytes memory data) public {
        vm.assume(value <= address(c).balance); // avoid overflow, keep test focused
        uint256 depositsBefore = c.depositsCount();
        (bool success, ) = address(c).call(abi.encodeWithSignature("sendMoney(address,uint256,bytes)", target, value, data));
        bool reverted = !success;
        if (reverted) {
            assertTrue(c.depositsCount() == depositsBefore, "depositsCount changed after revert");
        } else {
            assertTrue(c.depositsCount() == depositsBefore, "depositsCount changed after non-revert");
        }
    }
}
